-- 0002_read_indexes.sql — additive indexes that remove full-table scans (D1 free tier: 5M rows read / day).
-- Safe to run more than once (IF NOT EXISTS). Nothing is dropped, altered or rewritten; only indexes are created.
-- NOT applied automatically. Run it yourself, e.g.:
--   npx wrangler d1 execute <DB_NAME> --remote --file=cloudflare/migrations/0002_read_indexes.sql
-- Rollback: cloudflare/migrations/0002_read_indexes_rollback.sql
-- Column names / types were checked against 0001_init.sql; none of these indexes exist there.
-- The query shapes they serve are generated by functions/_lib/sb.js from the client calls listed beside each index.

-- travel_questions (9,307 rows): category pages  WHERE category_id=? ORDER BY order_num,id  (+ per-category counts)
CREATE INDEX IF NOT EXISTS idx_travel_q_cat_order ON travel_questions(category_id, order_num, id);

-- exam_questions (1,774 rows): licensure exam page  WHERE exam_id=? ORDER BY order_num
CREATE INDEX IF NOT EXISTS idx_exam_q_exam_order ON exam_questions(exam_id, order_num);

-- quiz_questions (468 rows): article quiz widgets  WHERE article_id=? AND type=? AND lang=? ORDER BY order_index
CREATE INDEX IF NOT EXISTS idx_quiz_q_article ON quiz_questions(article_id, type, lang, order_index);

-- course_questions / course_chapters: course pages  WHERE course_id=? ORDER BY order_num,id
CREATE INDEX IF NOT EXISTS idx_course_q_course_order ON course_questions(course_id, order_num, id);
CREATE INDEX IF NOT EXISTS idx_course_ch_course_order ON course_chapters(course_id, order_num, id);

-- drugs (398 rows): edge page check and detail lookups  WHERE slug=?
CREATE INDEX IF NOT EXISTS idx_drugs_slug ON drugs(slug);

-- applied_pharm_items (985 rows): /drugs/applied-pharm  WHERE part=? ORDER BY order_num
CREATE INDEX IF NOT EXISTS idx_applied_pharm_part_order ON applied_pharm_items(part, order_num);

-- smaller lookup tables filtered by category
CREATE INDEX IF NOT EXISTS idx_travel_review_cat_order ON travel_review_sections(category_id, order_num);
CREATE INDEX IF NOT EXISTS idx_interview_q_cat_order ON interview_questions(category_id, order_num);
CREATE INDEX IF NOT EXISTS idx_exams_cat_order ON exams(category_id, order_num);

-- live presence ping de-duplication  WHERE visitor_id=? AND created_at > ...  (was scanning every ping of the last 150 s)
CREATE INDEX IF NOT EXISTS idx_site_pings_visitor ON site_pings(visitor_id, created_at);

-- admin dashboard: installs per day / per month  WHERE created_at >= ? AND created_at < ?  (site_installs only had a visitor_id index)
CREATE INDEX IF NOT EXISTS idx_site_installs_created ON site_installs(created_at);
